import{XO_CONFIG as v}from"./config.min.js";const R=t=>t*t*(3-2*t),z=t=>1-(1-t)*(1-t),u=.82;export function landing(t,n=0){if(!(t>0))return 0;if(t>=1)return 1;if(t<u){const o=t/u;return o*o}return 1+n*Math.sin(Math.PI*(t-u)/(1-u))}export function contactFraction(t){const n=v.pose.takedown,o=Math.max(0,t-n.close),c=o>0?(t-n.contact)/o:0;if(!(c>0))return n.contactAt.min;if(c>=1)return n.contactAt.max;const e=1-Math.sqrt(1-c);return Math.min(n.contactAt.max,Math.max(n.contactAt.min,e))}export function takedownLength(t=1/0){const n=v.pose.takedown,o=Number.isFinite(t)?contactFraction(t):n.contactAt.max;return Math.max(n.dive,o*n.dive+n.fall)+n.settle}export function takedownAt(t,n,o,c=null){const e=v.pose.takedown,s=e.momentum,r=c&&c.velocity&&Number(c.velocity.x)||0,l=c&&c.velocity&&Number(c.velocity.z)||0,h=Math.hypot(r,l),a=h>s.still,T=a?r/h:0,Z=a?l/h:0,C=Math.hypot(o.x-n.x,o.z-n.z)||1e-6,i=contactFraction(C)*e.dive,y=a?Math.min(Math.max(0,t),i):0,G=r*y,O=l*y,k=o.x+r*(a?i:0)-n.x,g=o.z+l*(a?i:0)-n.z,d=Math.hypot(k,g)||1e-6,b=k/d,w=g/d,A=Math.max(0,d-e.close),x=Math.min(1,Math.max(0,t/e.dive)),M=Math.min(1,Math.max(0,(t-i)/e.fall)),F=z(Math.min(1,Math.max(0,(t-i)/(e.fall+e.skid)))),P=Math.sin(Math.PI*x)*e.leap,j=Math.max(0,1-M*1.6),N=a?s.keep*h*e.fall:0,f=b*e.driven+T*N,p=w*e.driven+Z*N,I=f*F,L=p*F;let X=0;const m=c&&Number.isFinite(c.facing)?c.facing:null;if(m!==null){const q=Math.hypot(f,p)||1,D=(f*-Math.cos(m)+p*Math.sin(m))/q;X=e.roll*D*R(M)}return{tackler:{x:b*A*z(x)+I*e.carry,y:P*j,z:w*A*z(x)+L*e.carry,lean:e.tacklerLean*landing(x,e.bounce)},carrier:{x:G+I,z:O+L,lean:e.carrierLean*landing(M,e.bounce),roll:X},contact:t>=i?1:0}}export function takedownRest(t,n,o=null){const c=Math.hypot(n.x-t.x,n.z-t.z),e=takedownLength(c),s=takedownAt(e,t,n,o);return{tackler:{x:t.x+s.tackler.x,z:t.z+s.tackler.z},carrier:{x:n.x+s.carrier.x,z:n.z+s.carrier.z},length:e}}export function tacklerFor(t,n){if(!n)return"";let o="",c=1/0;for(const e of t){if(e===n||e.settings.benched||e.settings.position==="ball"||e.settings.team===n.settings.team)continue;const s=Math.hypot(e.coords.x-n.coords.x,e.coords.y-n.coords.y);s<c&&(c=s,o=e.settings.position)}return o}
